:12px;padding:4px 10px;border-radius:5px;border:1px solid var(--line);color:var(--muted);background:var(--paper)}.tag.draft{color:var(--warn);background:var(--warnbg);border-color:transparent}section{padding-top:46px;margin-top:46px;border-top:1px solid var(--line);scroll-margin-top:26px}.section-no{color:var(--accent);font-size:13px;letter-spacing:.08em;margin-bottom:9px;font-weight:650}.callout{border-left:3px solid var(--accent);padding:18px 22px;background:var(--soft);margin:24px 0}.callout p:last-child{margin-bottom:0}.callout.open{border-color:var(--warn);background:var(--warnbg)}.callout strong{display:block;margin-bottom:8px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.panel{padding:22px;background:var(--paper);border:1px solid var(--line);border-radius:var(--radius)}.panel h3{margin:0 0 12px}.panel p:last-child{margin-bottom:0}.table-wrap{overflow:auto;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:14px;text-align:left}th{font-weight:650;color:var(--muted);background:var(--code);padding:13px 14px}td{padding:14px;vertical-align:top;border-bottom:1px solid var(--line);min-width:115px}caption{text-align:left;font-size:13px;color:var(--muted);margin-bottom:10px}.flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:24px 0}.flow .node{background:var(--paper);border:1px solid var(--line);padding:16px;border-radius:8px;min-height:92px}.node strong{display:block;font-size:15px}.node span{font-size:12px;color:var(--muted)}.node .number{font-size:12px;color:var(--accent);display:block;margin-bottom:5px}.node.selected{background:var(--soft);border-color:var(--accent)}.node.skipped{opacity:.55}.node.failed{background:var(--warnbg);border-color:var(--warn)}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.controls button,.print{background:var(--paper);border:1px solid var(--line);color:var(--ink);border-radius:6px;padding:9px 14px;font-size:14px}.controls button[aria-pressed=true]{background:var(--accent);color:var(--bg);border-color:var(--accent)}.scenario{padding:20px;background:var(--code);border-radius:8px;min-height:110px}.scenario h3{margin:0 0 10px}.scenario p{margin:0}.footnote{font-size:13px;color:var(--muted)}details{border-top:1px solid var(--line);padding:15px 0;margin-top:15px}summary{cursor:pointer;font-weight:600}.contract{font-size:13px;letter-spacing:.06em;color:var(--accent);font-weight:700;margin-bottom:8px}.decision{display:grid;grid-template-columns:65px 1fr;gap:15px;border-top:1px solid var(--line);padding:20px 0}.decision-id{font:600 13px ui-monospace,monospace;color:var(--warn);padding-top:3px}.decision h3{margin:0 0 9px}.decision p{margin-bottom:10px}.refs li{font-size:14px}.skip{position:absolute;left:10px;top:-90px;padding:12px;background:var(--paper);z-index:10}.skip:focus{top:10px}footer{border-top:1px solid var(--line);margin-top:55px;padding-top:24px;color:var(--muted);font-size:13px}.mobile-nav{display:none}.stage-lanes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.stage-lanes .panel{border-top:3px solid var(--accent)}.stage-lanes ul{font-size:14px;margin-bottom:0}.status{font-weight:600;color:var(--accent)}
