    n("areas"),
    ExpressionBody([], ty("morphir/SDK:list#list", args=[float]),
      call("morphir/SDK:list#map", [Reference(v(), fq("acme/shapes:geometry#area")), local("shapes")])),
    call("morphir/SDK:list#sum", [local("areas")]),
  )
  let scaled = @ir.Value::Lambda(v(), AsPattern(v(), WildcardPattern(v()), n("s")),
    @ir.Value::UpdateRecord(v(), local("s"), Map::from_array([(n("scale"), Literal(v(), FloatLiteral(2.0)))])))
  library("acme/shapes", [
