test "records, fields and updates" {
  let ctx = ctx_for()
  ignore(ctx.bind(n("order")))
  let record = @ir.Value::Record(va(), Map::from_array([(n("total"), int("1"))]))
  assert_eq(show(ctx, record), "{ total = 1 }")
  assert_eq(show(ctx, @ir.Value::Field(va(), var("order"), n("total"))), "order.total")
  assert_eq(show(ctx, @ir.Value::FieldFunction(va(), n("total"))), ".total")
  let update = @ir.Value::UpdateRecord(va(), var("order"), Map::from_array([(n("total"), int("2"))]))
  assert_eq(show(ctx, update), "{ order | total = 2 }")
  // A non-variable target is bound first; Elm only updates a named record.
  let nested = @ir.Value::UpdateRecord(va(), record, Map::from_array([(n("total"), int("2"))]))
  let printed = show(ctx, nested)
  assert_true(printed.contains("record_1 =") && printed.contains("{ record_1 | total = 2 }"))
