  assert_false(printed.contains("total :")) // no signatures in let
  let branch = @ir.Value::IfThenElse(va(), @ir.Value::Literal(va(), BoolLiteral(true)), int("1"), int("2"))
  assert_true(show(ctx, branch).has_prefix("if True then"))
  let case_value = @ir.Value::PatternMatch(va(), int("1"), [
