```moonbit
///|
fn Ctx::reserve_top_level(self : Ctx, elm_name : String) -> Unit {
  self.used[elm_name] = true
}

///|
/// Elm rejects a local name that shadows any name in scope, so a taken name gets a numeric suffix.
fn Ctx::bind(self : Ctx, name : @ir.Name) -> String {
  let base = value_name(name)
  let mut elm_name = base
  while self.used.contains(elm_name) {
    self.fresh += 1
    elm_name = base + "_" + self.fresh.to_string()
  }
  self.used[elm_name] = true
  self.scope[name.to_canonical()] = elm_name
  elm_name
}

///|
fn[T] Ctx::with_scope(
  self : Ctx,
  body : () -> T raise ElmGenerationError,
) -> T raise ElmGenerationError {
  let saved = self.scope.copy()
  let result = body() catch {
    error => {
      self.scope = saved
      raise error
    }
  }
  self.scope = saved
  result
}

///|
fn Ctx::fresh_name(self : Ctx, base : String) -> String {
  self.fresh += 1
  let name = base + "_" + self.fresh.to_string()
  self.used[name] = true
  name
}

///|
fn placeholder(ctx : Ctx, reason : String, at : String) -> @ast.Expression raise ElmGenerationError {
  match ctx.options.placeholders {
    Refuse => refuse("placeholder", at, reason)
    DebugTodo =>
      Application([node(FunctionOrValue(["Debug"][:], "todo")), node(Literal(reason))][:])
  }
}

///|
fn hole_reason(reason : @ir.HoleReason) -> String {
  match reason {
    UnresolvedReference(name) => "hole: unresolved reference " + name.to_canonical()
    DeletedDuringRefactor(detail) => "hole: deleted during refactor: " + detail
    TypeMismatch(expected, found) => "hole: type mismatch, expected " + expected + ", found " + found
  }
}

///|
fn int_expression(text : String, at : String) -> @ast.Expression raise ElmGenerationError {
  let value = @strconv.parse_int64(text) catch {
    _ => refuse("int_literal", at, text + " is outside the Int64 range")
  }
  if value < 0L {
    if value == -9223372036854775808L {
      refuse("int_literal", at, text + " has no positive Int64 form")
    }
    Negation(node(Integer(-value)))
  } else {
    Integer(value)
  }
}

///|
fn lower_literal(lit : @ir.Literal, at : String) -> @ast.Expression raise ElmGenerationError {
  match lit {
    BoolLiteral(b) => FunctionOrValue([][:], if b { "True" } else { "False" })
    CharLiteral(c) => CharLiteral(c)
    StringLiteral(s) => Literal(s)
    IntegerLiteral(text) => int_expression(text, at)
    FloatLiteral(d) =>
      if d < 0.0 || (d == 0.0 && 1.0 / d < 0.0) {
        Negation(node(Floatable(-d)))
      } else {
        Floatable(d)
      }
    DecimalLiteral(text) =>
      refuse("decimal_literal", at, "no Elm construction is mapped for decimal " + text)
    DocumentLiteral(_) => refuse("document_literal", at, "Elm has no document literal")
  }
}

///|
fn reference(ctx : Ctx, name : @ir.FQName, kind : Kind) -> @ast.Expression {
  match ctx.resolve(name, kind) {
    Qualified(qualifier, local) => FunctionOrValue(qualifier[:], local)
    Op(op) => PrefixOperator(op)
  }
}

///|
fn operator_direction(op : String) -> @ast.InfixDirection {
  match op {
    "^" | "++" | "::" | "&&" | "||" | ">>" => Right
    "==" | "/=" | "<" | ">" | "<=" | ">=" => Non
    _ => Left
  }
}

///|
fn lower_apply(ctx : Ctx, v : @ir.Value, at : String) -> @ast.Expression raise ElmGenerationError {
  let args = []
  let mut head = v
  while head is Apply(_, f, a) {
    args.push(a)
    head = f
  }
  args.rev_in_place()
  let lowered = args.map(a => node(lower_value(ctx, a, at)))
  let op = match head {
    Reference(_, name) =>
      match ctx.resolve(name, Lower) {
        Op(op) => Some(op)
        Qualified(_, _) => None
      }
    _ => None
  }
  match op {
    Some(op) if lowered.length() >= 2 => {
      let infix = node(@ast.Expression::OperatorApplication(op, operator_direction(op), lowered[0], lowered[1]))
      if lowered.length() == 2 {
        infix.value
      } else {
        Application(([node(ParenthesizedExpression(infix))] + lowered[2:].to_array())[:])
      }
    }
    Some(op) => Application(([node(PrefixOperator(op))] + lowered)[:])
    None => Application(([node(lower_value(ctx, head, at))] + lowered)[:])
  }
}

///|
fn lower_pattern(ctx : Ctx, p : @ir.Pattern, at : String) -> @ast.Pattern raise ElmGenerationError {
  match p {
    WildcardPattern(_) => AllPattern
    AsPattern(_, WildcardPattern(_), name) => VarPattern(ctx.bind(name))
    AsPattern(_, inner, name) => {
      let lowered = lower_pattern(ctx, inner, at)
      AsPattern(node(lowered), node(ctx.bind(name)))
    }
    TuplePattern(_, items) => {
      check_tuple_arity(items.length(), at)
      TuplePattern(items.map(i => node(lower_pattern(ctx, i, at)))[:])
    }
    ConstructorPattern(_, name, args) => {
      let (qualifier, local) = match ctx.resolve(name, Upper) {
        Qualified(q, l) => (q, l)
        Op(op) => refuse("invalid_mapping", at, "constructor maps to operator " + op)
      }
      NamedPattern({ module_name: qualifier[:], name: local }, args.map(a => node(lower_pattern(ctx, a, at)))[:])
    }
    EmptyListPattern(_) => ListPattern([][:])
    HeadTailPattern(_, head, tail) =>
      UnConsPattern(node(lower_pattern(ctx, head, at)), node(lower_pattern(ctx, tail, at)))
    LiteralPattern(_, literal) =>
      match literal {
        BoolLiteral(b) => NamedPattern({ module_name: [][:], name: if b { "True" } else { "False" } }, [][:])
        CharLiteral(c) => CharPattern(c)
        StringLiteral(s) => StringPattern(s)
        IntegerLiteral(text) =>
          match int_expression(text, at) {
            Integer(v) => IntPattern(v)
            _ => refuse("literal_pattern", at, "Elm has no negative literal pattern: " + text)
          }
        FloatLiteral(_) | DecimalLiteral(_) =>
          refuse("literal_pattern", at, "Elm has no float or decimal pattern")
      }
    UnitPattern(_) => UnitPattern
  }
}

///|
fn setters(
  ctx : Ctx,
  fields : Map[@ir.Name, @ir.Value],
  at : String,
) -> ArrayView[@ast.Node[@ast.RecordSetter]] raise ElmGenerationError {
  let result = []
  for name, value in fields {
    result.push(node({ field: node(value_name(name)), expression: node(lower_value(ctx, value, at)) }))
  }
  result[:]
}

///|
fn let_function(
  ctx : Ctx,
  elm_name : String,
  definition : @ir.ValueDefinition,
  at : String,
) -> @ast.LetDeclaration raise ElmGenerationError {
  let (arguments, expression) = match definition {
    ExpressionBody(inputs, _, body) => function_body(ctx, inputs, body, at)
    _ => ([][:], node(placeholder(ctx, "a let definition without an expression body", at)))
  }
  LetFunction({
    documentation: None,
    signature: None,
    declaration: node({ name: node(elm_name), arguments, expression }),
  })
}

///|
fn function_body(
  ctx : Ctx,
  inputs : Array[(@ir.Name, @ir.Type)],
  body : @ir.Value,
  at : String,
) -> (ArrayView[@ast.Node[@ast.Pattern]], @ast.Node[@ast.Expression]) raise ElmGenerationError {
  ctx.with_scope(fn() raise ElmGenerationError {
    let arguments = inputs.map(input => node(@ast.Pattern::VarPattern(ctx.bind(input.0))))
    (arguments[:], node(lower_value(ctx, body, at)))
  })
}

///|
fn lower_let(ctx : Ctx, v : @ir.Value, at : String) -> @ast.Expression raise ElmGenerationError {
  ctx.with_scope(fn() raise ElmGenerationError {
    let declarations = []
    let mut rest = v
    while true {
      match rest {
        LetDefinition(_, name, definition, next) => {
          // The definition sees the outer binding of its own name, so bind after lowering.
          let body = let_function(ctx, "", definition, at)
          let elm_name = ctx.bind(name)
          declarations.push(node(rename_let(body, elm_name)))
          rest = next
        }
        LetRecursion(_, definitions, next) => {
          let names = definitions.keys().map(name => (name, ctx.bind(name))).collect()
          for pair in names {
            declarations.push(node(let_function(ctx, pair.1, definitions.get(pair.0).unwrap(), at)))
          }
          rest = next
        }
        Destructure(_, pattern, value, next) => {
          let lowered_value = node(lower_value(ctx, value, at))
          let lowered_pattern = node(lower_pattern(ctx, pattern, at))
          declarations.push(node(@ast.LetDeclaration::LetDestructuring(lowered_pattern, lowered_value)))
          rest = next
        }
        _ => break
      }
    }
    LetExpression({ declarations: declarations[:], expression: node(lower_value(ctx, rest, at)) })
  })
}

///|
fn rename_let(declaration : @ast.LetDeclaration, elm_name : String) -> @ast.LetDeclaration {
  match declaration {
    LetFunction(f) =>
      LetFunction({
        ..f,
        declaration: node({ ..f.declaration.value, name: node(elm_name) }),
      })
    other => other
  }
}

///|
fn lower_value(ctx : Ctx, v : @ir.Value, at : String) -> @ast.Expression raise ElmGenerationError {
  match v {
    Literal(_, literal) => lower_literal(literal, at)
    Constructor(_, name) => reference(ctx, name, Upper)
    Tuple(_, items) => {
      check_tuple_arity(items.length(), at)
      TupledExpression(items.map(i => node(lower_value(ctx, i, at)))[:])
    }
    List(_, items) => ListExpr(items.map(i => node(lower_value(ctx, i, at)))[:])
    Record(_, fields) => RecordExpr(setters(ctx, fields, at))
    Variable(_, name) =>
      match ctx.scope.get(name.to_canonical()) {
        Some(elm_name) => FunctionOrValue([][:], elm_name)
        None => FunctionOrValue([][:], value_name(name))
      }
    Reference(_, name) => reference(ctx, name, Lower)
    Field(_, target, name) => RecordAccess(node(lower_value(ctx, target, at)), node(value_name(name)))
    FieldFunction(_, name) => RecordAccessFunction("." + value_name(name))
    Apply(_, _, _) => lower_apply(ctx, v, at)
    Lambda(_, _, _) =>
      ctx.with_scope(fn() raise ElmGenerationError {
        let args = []
        let mut body = v
        while body is Lambda(_, pattern, next) {
          args.push(node(lower_pattern(ctx, pattern, at)))
          body = next
        }
        LambdaExpression({ args: args[:], expression: node(lower_value(ctx, body, at)) })
      })
    LetDefinition(_, _, _, _) | LetRecursion(_, _, _) | Destructure(_, _, _, _) => lower_let(ctx, v, at)
    IfThenElse(_, condition, then_branch, else_branch) =>
      IfBlock(
        node(lower_value(ctx, condition, at)),
        node(lower_value(ctx, then_branch, at)),
        node(lower_value(ctx, else_branch, at)),
      )
    PatternMatch(_, subject, cases) => {
      let lowered_subject = node(lower_value(ctx, subject, at))
      let lowered_cases = cases.map(c => {
        ctx.with_scope(fn() raise ElmGenerationError {
          let pattern = node(lower_pattern(ctx, c.0, at))
          { pattern, expression: node(lower_value(ctx, c.1, at)) }
        })
      })
      CaseExpression({ expression: lowered_subject, cases: lowered_cases[:] })
    }
    UpdateRecord(_, target, fields) =>
      match target {
        Variable(_, _) => {
          let record = match lower_value(ctx, target, at) {
            FunctionOrValue(_, name) => name
            _ => panic()
          }
          RecordUpdateExpression(node(record), setters(ctx, fields, at))
        }
        _ => {
          let fresh = ctx.fresh_name("record")
          let bound = node(@ast.LetDeclaration::LetFunction({
            documentation: None,
            signature: None,
            declaration: node({ name: node(fresh), arguments: [][:], expression: node(lower_value(ctx, target, at)) }),
          }))
          LetExpression({
            declarations: [bound][:],
            expression: node(RecordUpdateExpression(node(fresh), setters(ctx, fields, at))),
          })
        }
      }
    Unit(_) => UnitExpr
    Hole(_, reason, _) => placeholder(ctx, hole_reason(reason), at)
  }
}
```

Implementation notes for the engineer:
- The `LetDefinition` branch lowers the definition body **before** it binds the name, so `let total = total + 1`
  refers to the outer `total`. Keep that order.
- Check `RecordAccessFunction`: elm-syntax 7.3.9 stores the name **with** the leading dot. If the printer prints
  `..total`, drop the `"." +`. The test `".total"` decides.

