```moonbit
///|
priv enum TypeSource {
  Defined(@ir.TypeDefinition)
  Specified(@ir.TypeSpecification)
}

///|
priv enum ValueSource {
  DefinedValue(@ir.ValueDefinition)
  SpecifiedValue(@ir.ValueSpecification)
}

///|
priv struct ModuleInput {
  package_name : @ir.Path
  module : @ir.Path
  doc : String?
  types : Array[(@ir.Name, @ir.Access, String?, TypeSource)]
  values : Array[(@ir.Name, @ir.Access, String?, ValueSource)]
  entry_points : Map[String, @ir.EntryPoint]
}

///|
fn ModuleInput::from_definition(
  package_name : @ir.Path,
  module : @ir.Path,
  definition : @ir.ModuleDefinition,
  entry_points : Map[String, @ir.EntryPoint],
) -> ModuleInput {
  {
    package_name,
    module,
    doc: definition.doc,
    types: definition.types
      .iter()
      .map(entry => (entry.0, entry.1.access, entry.1.value.doc, Defined(entry.1.value.value)))
      .collect(),
    values: definition.values
      .iter()
      .map(entry => (entry.0, entry.1.access, entry.1.value.doc, DefinedValue(entry.1.value.value)))
      .collect(),
    entry_points,
  }
}

///|
fn ModuleInput::from_specification(
  package_name : @ir.Path,
  module : @ir.Path,
  spec : @ir.ModuleSpecification,
) -> ModuleInput {
  {
    package_name,
    module,
    doc: spec.doc,
    types: spec.types.iter().map(entry => (entry.0, @ir.Access::Public, entry.1.doc, Specified(entry.1.value))).collect(),
    values: spec.values
      .iter()
      .map(entry => (entry.0, @ir.Access::Public, entry.1.doc, SpecifiedValue(entry.1.value)))
      .collect(),
    entry_points: Map([]),
  }
}

///|
priv struct ModuleOutput {
  elm_module : Array[String]
  source : String
  uses_sdk_package : Bool
  foreign_packages : Array[String]
}

///|
fn elm_string(text : String) -> String {
  "\"" + text.replace_all(old="\\", new="\\\\").replace_all(old="\"", new="\\\"") + "\""
}

///|
fn entry_kind(kind : @ir.EntryPointKind) -> String {
  match kind {
    Main => "main"
    Command => "command"
    Handler => "handler"
    Job => "job"
    Policy => "policy"
  }
}

///|
fn annotation_attribute(ctx : Ctx, annotation : @ir.Annotation, at : String) -> String raise ElmGenerationError {
  match annotation {
    Compact(name, text) =>
      "@morphir.annotation { fqname = " + elm_string(name.to_canonical()) +
      (match text {
        Some(t) => ", text = " + elm_string(t)
        None => ""
      }) + " }"
    Structured(name, arguments) => {
      let printed = arguments.map(argument => {
        match argument {
          Positional(value) =>
            "{ value = " + @printer.print_expression(node(lower_value(ctx, value, at))) + " }"
          Named(field, value) =>
            "{ name = " + elm_string(field.to_canonical()) + ", value = " +
            @printer.print_expression(node(lower_value(ctx, value, at))) + " }"
        }
      }) catch {
        Refused(_) as e => raise e
        e => refuse("print", at, e.to_string())
      }
      "@morphir.annotation { fqname = " + elm_string(name.to_canonical()) + ", arguments = [ " +
      printed.join(", ") + " ] }"
    }
  }
}

///|
fn signature(
  ctx : Ctx,
  elm_name : String,
  inputs : Array[(@ir.Name, @ir.Type)],
  output : @ir.Type,
  at : String,
) -> @ast.Node[@ast.Signature] raise ElmGenerationError {
  let mut result = lower_type(ctx, output, at)
  for i = inputs.length() - 1; i >= 0; i = i - 1 {
    result = FunctionTypeAnnotation(node(lower_type(ctx, inputs[i].1, at)), node(result))
  }
  node({ name: node(elm_name), type_annotation: node(result) })
}

///|
fn value_declaration(
  ctx : Ctx,
  elm_name : String,
  doc : String?,
  source : ValueSource,
  attributes : Array[String],
  at : String,
) -> @ast.Declaration raise ElmGenerationError {
  let attributes = attributes.copy()
  let (inputs, output, body) : (Array[(@ir.Name, @ir.Type)], @ir.Type?, @ir.Value?) = match source {
    DefinedValue(ExpressionBody(inputs, output, body)) => (inputs, Some(output), Some(body))
    DefinedValue(NativeBody(inputs, output, _)) => (inputs, Some(output), None)
    DefinedValue(ExternalBody(inputs, output, bindings, fallback)) => {
      for binding in bindings {
        attributes.push(
          "@morphir.external { platform = " + elm_string(binding.target_platform) + ", name = " +
          elm_string(binding.external_name) + " }",
        )
      }
      (inputs, Some(output), fallback)
    }
    DefinedValue(IncompleteBody(inputs, output, _, _)) => (inputs, output, None)
    SpecifiedValue(spec) => {
      for annotation in spec.annotations {
        attributes.push(annotation_attribute(ctx, annotation, at))
      }
      (spec.inputs, Some(spec.output), None)
    }
  }
  let reason = match source {
    DefinedValue(NativeBody(_, _, _)) => "native body"
    DefinedValue(ExternalBody(_, _, _, _)) => "external body without a fallback"
    DefinedValue(IncompleteBody(_, _, _, _)) => "incomplete definition"
    _ => "specification without a body"
  }
  let (arguments, expression) = match body {
    Some(value) => function_body(ctx, inputs, value, at)
    None =>
      ctx.with_scope(fn() raise ElmGenerationError {
        let arguments = inputs.map(input => node(@ast.Pattern::VarPattern(ctx.bind(input.0))))
        (arguments[:], node(placeholder(ctx, reason, at)))
      })
  }
  FunctionDeclaration({
    documentation: doc_comment(doc, attributes),
    signature: match output {
      Some(t) => Some(signature(ctx, elm_name, inputs, t, at))
      None => None
    },
    declaration: node({ name: node(elm_name), arguments, expression }),
  })
}

///|
fn generate_module(options : Options, input : ModuleInput) -> ModuleOutput raise ElmGenerationError {
  let ctx = Ctx::new(options, input.package_name, input.module)
  let elm_module = module_name(input.package_name, input.module)
  let fq = fn(name : @ir.Name) {
    input.package_name.to_canonical() + ":" + input.module.to_canonical() + "#" + name.to_canonical()
  }
  // Top-level names first: they are in scope everywhere, and a collision is an error.
  let value_names : Map[String, String] = Map([])
  for value in input.values {
    let elm_name = value_name(value.0)
    if value_names.values().any(existing => existing == elm_name) {
      refuse("name_collision", fq(value.0), "another value in this module is also " + elm_name)
    }
    value_names[value.0.to_canonical()] = elm_name
    ctx.reserve_top_level(elm_name)
  }
  let type_names : Map[String, Bool] = Map([])
  for t in input.types {
    let elm_name = type_name(t.0)
    if type_names.contains(elm_name) {
      refuse("name_collision", fq(t.0), "another type in this module is also " + elm_name)
    }
    type_names[elm_name] = true
  }
  let declarations : Array[(String, @ast.Node[@ast.Declaration])] = []
  let exposes : Array[@ast.Node[@ast.TopLevelExpose]] = []
  for t in input.types {
    let at = fq(t.0)
    let (declaration, expose) = match t.3 {
      Defined(definition) => lower_type_definition(ctx, t.0, t.2, definition, at)
      Specified(spec) => {
        let (d, e) = lower_type_specification(ctx, t.0, t.2, spec, at)
        (d, Some(e))
      }
    }
    declarations.push((at, node(declaration)))
    if t.1 is Public && expose is Some(e) {
      exposes.push(node(e))
    }
  }
  for value in input.values {
    let at = fq(value.0)
    let elm_name = value_names.get(value.0.to_canonical()).unwrap()
    let attributes = []
    for key, entry in input.entry_points {
      if entry.target.to_canonical() == at {
        attributes.push("@morphir.entry { kind = " + elm_string(entry_kind(entry.kind)) + ", name = " + elm_string(key) + " }")
      }
    }
    declarations.push((at, node(value_declaration(ctx, elm_name, value.2, value.3, attributes, at))))
    if value.1 is Public {
      exposes.push(node(FunctionExpose(elm_name)))
    }
  }
  let exposing : @ast.Exposing = if exposes.is_empty() { All(zero) } else { Explicit(exposes[:]) }
  let file : @ast.File = {
    module_definition: node(NormalModule({ module_name: node(elm_module[:]), exposing_list: node(exposing) })),
    imports: ctx.elm_imports()[:],
    declarations: declarations.map(d => d.1)[:],
    comments: match doc_comment(input.doc, []) {
      Some(comment) => [comment][:]
      None => [][:]
    },
  }
  let source = @printer.print_file(file, width=options.width) catch {
    error => {
      // Find the declaration that does not print, to report its IR path.
      for d in declarations {
        @printer.print_declaration(d.1, width=options.width) catch {
          inner => refuse("print", d.0, inner.to_string())
        }
      }
      refuse("print", elm_module.join("."), error.to_string())
    }
  }
  {
    elm_module,
    source,
    uses_sdk_package: ctx.uses_sdk_package,
    foreign_packages: ctx.foreign_packages.keys().collect(),
  }
}
```

Implementation notes for the engineer:
- `print_declaration` returns a `String`; wrap the per-declaration call as `ignore(@printer.print_declaration(...))`
  inside a `try ... catch`.
- **Module documentation:** the test "module documentation is printed" checks that krueger prints the module doc
  comment from `File.comments`. If krueger 0.4.0 does not print it (its changelog says regular comments are not
  printed), insert the doc comment text after the module line yourself: split `source` at the first `"\n\n"` and
  join the parts with `"\n\n" + comment + "\n"`. Then check that the result still parses with no diagnostics.
- If a `@printer.print_*` call needs `dialect`, leave it at its default (`elm make` rules).

