/// What a backend can generate.
pub type BackendCapability {
  BackendCapability(targets: List(String), ir_versions: List(String), generate: Bool)
}

/// Workspace discovery support. Each protocol version is a SemVer string.
pub type WorkspaceCapability {
  WorkspaceCapability(protocol_versions: List(String), discover: Bool)
}

/// What an extension can do. The four flags are always written. Members of
/// `extra` sit beside the named members on the wire, not under an `extra`
/// key; a host rejects extra members that reuse a named member's wire name.
pub type ExtensionCapabilities {
  ExtensionCapabilities(
    frontend: Option(FrontendCapability),
    backend: Option(BackendCapability),
    workspace: Option(WorkspaceCapability),
    streaming: Bool,
    incremental: Bool,
    cancellation: Bool,
    progress: Bool,
    extra: Dict(String, Json),
  )
}

/// Host requirements of a claim set. Each entry is a SemVer comparator such as
